import csv,json,os,collections
from pathlib import Path
rows=[r for r in csv.DictReader(open('D1/in/part-flatcar.tsv'),delimiter='\t') if r['kind']=='L2:stored-outside-packages']
parts=Path('D1/in/raw/flatcar/raw/105-filesystem.out').read_bytes().decode().split('\0')
fs={parts[i]:parts[i+1:i+6] for i in range(0,len(parts)-6,6)}
OUT=Path('D1/c1/part-flatcar.stored.tsv'); NOTES=Path('D1/c1/part-flatcar.stored.notes.md')
header=['id','decision','sentences','what_it_does','basis','reason']
if not OUT.exists():OUT.write_text('\t'.join(header)+'\n')
existing={r['id'] for r in csv.DictReader(OUT.open(),delimiter='\t')}
RAW='raw:flatcar/raw/105-filesystem.out'
def put(i,decision,sentences,what,reason,basis=RAW):
 r=rows[i]
 assert len(what.split())<=15,(i,what)
 assert len(reason.split())<=30,(i,reason)
 if r['id'] not in existing:
  with OUT.open('a') as f: csv.writer(f,delimiter='\t',lineterminator='\n').writerow([r['id'],decision,sentences,what,basis,reason])
  existing.add(r['id'])
def note(s):
 with NOTES.open('a') as f:f.write(s+'\n')
def mixed(i,what,groups,reason,sentences='S2.2-1,S2.2-2,S2.2-4,S2.2-6,S3-2',basis=RAW):
 members=json.loads(rows[i]['members']); assignments={}
 for dec,indices in groups.items():
  if indices=='rest':continue
  for j in indices:assignments[j]=dec
 if any(v=='rest' for v in groups.values()):
  dec=next(k for k,v in groups.items() if v=='rest')
  assignments.update({j:dec for j in range(1,len(members)+1) if j not in assignments})
 assert set(assignments)==set(range(1,len(members)+1)),(i,assignments)
 label='; '.join(dec+'='+','.join(str(j) for j in sorted(assignments) if assignments[j]==dec) for dec in groups)
 put(i,'MIXED',sentences,what,label+'. '+reason,basis)
 note('\n### '+rows[i]['id']+'\nMember numbers are one-based input-array positions. '+reason)
 for j,m in enumerate(members,1): note(f'- {j}: `{m}` — {assignments[j]}')

if not NOTES.exists():
 note('# Stored objects: independent classification notes\n\nScope: only L2:stored-outside-packages rows. Inventory labels were disregarded. The raw filesystem snapshot stores path, type, mode, uid, gid, and link target in six NUL-delimited fields. It does not contain arbitrary file contents. Directories listed as members are considered with their contents; grouping never implies homogeneous membership. No objects were removed. UNKNOWN identifies unavailable actual consumers or contents, not a defect concerning system-design treatment of state.\n')
 for line in Path('SENTENCES.md').read_text().splitlines():
  if any('**'+s+'**' in line for s in ['S2.2-1','S2.2-2','S2.2-4','S2.2-5','S2.2-6','S2.2-7','S2.2-9','S2.2-10','S2.2-11','S2.2-12','S2.2-13','S2.2-15','S3-1','S3-2']):note(line)
 note('\n## Rule U: udev link-stack entries\nFor each group strictly under /run/udev/links/, every member is the recorded priority/device association used when udev chooses the target of a device alias. Removing it eliminates that candidate during subsequent link updates. Device alias behavior is therefore dependent on these objects (S2.2-1, S2.2-2), and they are neither historical records nor a speed-only cache. MUST. This is runtime device-management state, not a user setting confined to an application.\nSource: https://raw.githubusercontent.com/systemd/systemd/main/src/udev/udev-node.c\nExact quote: “This reads priority and device node from the symlink under /run/udev/links/ directory.”\nThe function stack_directory_find_prioritized_devnode selects among these candidates; link_search_and_update deletes the alias when no reference remains.\nHand-checked 10 groups against both raw type/target and the input members:')
 for i in [156,157,191,200,228,250,296,308,311,315]:
  r=rows[i]; note('- '+r['id']+': '+r['name']+'; '+', '.join(fs[m][-1] for m in json.loads(r['members']))+'. All members are priority/device links; the multi-candidate group also fits.')
 note('\n## Rule K: empty-directory package markers\nA group consisting entirely of .keep_* regular files contains package bookkeeping markers, not settings, executable code or device/access rules. Removing the marker alone leaves the directory and program functions intact. NOT (S2.2-2, S2.2-4).\nSource: https://devmanual.gentoo.org/function-reference/install-functions/index.html\nExact quote: “This is accomplished by installing a hidden file prefixed with `.keep` to the directory in question.”\nHand-checked IDs below:')
 for i in [23,27,28,37,38,40,43,46,50,51]:note('- '+rows[i]['id']+': '+rows[i]['members']+'; raw records regular .keep files, with no other group members.')
for i,r in enumerate(rows):
 if r['name'].startswith('/run/udev/links/'):
  put(i,'MUST','S2.2-1,S2.2-2','Provide priority and device targets for udev device-alias selection.','Removing these candidates changes which device aliases udev maintains; their effect is not confined to one program.','doc:https://raw.githubusercontent.com/systemd/systemd/main/src/udev/udev-node.c')
 elif all(Path(m).name.startswith('.keep_') for m in json.loads(r['members'])):
  put(i,'NOT','S2.2-2,S2.2-4','Keep otherwise empty directories tracked by the package manager.','Marker removal leaves the directory and runtime functionality intact; only package bookkeeping content is unavailable.','doc:https://devmanual.gentoo.org/function-reference/install-functions/index.html')
