def must(i,what,reason,basis=RAW,sentences='S2.2-1,S2.2-2'):put(i,'MUST',sentences,what,reason,basis)
def not_(i,what,reason,basis=RAW,sentences='S2.2-4'):put(i,'NOT',sentences,what,reason,basis)
def hole(i,what,reason,basis=RAW,sentences='S2.2-1,S2.2-6'):put(i,'HOLE',sentences,what,reason,basis)
